using MallEnergyBilling.Web.Models;using MallEnergyBilling.Web.Services;namespace MallEnergyBilling.Tests;
public sealed class TariffResolverTests{[Fact]public void ResolvesTariffIndependentlyForEachMeter(){var at=new DateTimeOffset(2026,8,25,0,0,0,TimeSpan.Zero);var tariffs=new[]{new Tariff{MeterId=1,PricePerKwh=.22m,EffectiveFrom=at.AddDays(-10)},new Tariff{MeterId=2,PricePerKwh=.31m,EffectiveFrom=at.AddDays(-10)},new Tariff{MeterId=1,PricePerKwh=.25m,EffectiveFrom=at.AddDays(1)}};var resolver=new TariffResolver();Assert.Equal(.22m,resolver.Resolve(tariffs,1,at).PricePerKwh);Assert.Equal(.31m,resolver.Resolve(tariffs,2,at).PricePerKwh);}}
